steps.script:
var d = tree.root.get_node_or_null("StratagemDialog")
if d and d.visible and int(PhaseManager.get_current_phase_instance().get_pending_stratagem_window_decider()) == 1:
	d.get_node("Content/DeclineButton").emit_signal("pressed")
return true

var d = tree.root.get_node_or_null("StratagemDialog")
if d and d.visible and int(PhaseManager.get_current_phase_instance().get_pending_stratagem_window_decider()) == 2:
	d.get_node("Content/DeclineButton").emit_signal("pressed")
return true

var ev: Array = PhaseManager.get_current_phase_instance().resolution_state.get("staged_hit_context", {}).get("hit_evals", [])
for i in range(ev.size()):
	if not bool(ev[i].get("is_hit", false)):
		return i
return -1

var n := 0
for e in GameEventLog.entries:
	if str(e.get("text", "")).find("Advanced Firepower: Caladius Annihilator Grav-Tank re-rolls one hit roll (") >= 0:
		n += 1
return n

var panel = null
for n in tree.root.get_node("Main").find_children("*", "", true, false):
	if n.get("_tab_dice_button") != null:
		panel = n
		break
if panel == null:
	return "panel not found"
if panel.get("_tab_game_button") != null:
	panel._tab_game_button.emit_signal("pressed")
return true

var d = tree.root.get_node_or_null("StratagemDialog")
if d and d.visible and int(PhaseManager.get_current_phase_instance().get_pending_stratagem_window_decider()) == 2:
	d.get_node("Content/DeclineButton").emit_signal("pressed")
return true

var ev: Array = PhaseManager.get_current_phase_instance().resolution_state.get("staged_wound_context", {}).get("wound_evals", [])
for i in range(ev.size()):
	if not bool(ev[i].get("is_wound", false)):
		return i
return -1

